insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (3, 1, 'ആമുഖമായി', '39', '40') on conflict do nothing;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'heading', 'ആമുഖമായി', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=1);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'അൽഹംദുലില്ലാഹ്, അല്ലാഹുവിന്ന് സ്തുതി. അസ്സിഹാഹുസ്സിത്ത:യുടെ മൂന്നാം ഭാഗത്തിന്റെ രണ്ടാം പതിപ്പ് പുറത്തിറങ്ങുകയാണ്. ജീവിതകാലത്ത് പൂർത്തിയാക്കാൻ സാധിക്കുമെന്ന് വിചാരിച്ചല്ല ഈ സംരംഭം തുടങ്ങിയത്. ഖുർആനും സുന്നത്തു(നബിചര്യ)മാണ് ഇസ്ലാമിന്റെ അടിസ്ഥാനമെങ്കിൽ അവ എല്ലാ മുസ്ലിംകളും അറിഞ്ഞിരിക്കേണ്ടതല്ലേ എന്ന ചിന്തയിൽ നിന്നാണ് ഹദീസുകളെക്കുറിച്ച് അന്വേഷിക്കാനാരംഭിച്ചത്. ഇരുപത്തഞ്ച് വർഷങ്ങൾക്ക് മുമ്പാണത്. എല്ലാ ഹദീസുകളും ശേഖരിക്കാൻ തന്നെ ഒരു വർഷമെടുത്തു. എല്ലാംകൂടി നാൽപതിലധികം വാല്യങ്ങളുണ്ട്. ആവർത്തനങ്ങളൊഴിവാക്കി എങ്ങനെ തയ്യാറാക്കാം എന്ന ഗവേഷണമായിരുന്നു അഞ്ചുവർഷം. അല്ലാഹു മാർഗ്ഗം കാണിച്ചുതന്നു. അതിന്റെ ഫലമാണ് അസ്സിഹാഹുസ്സിത്ത: എന്ന ഈ വാല്യങ്ങൾ.', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=2);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', '"റസൂൽ(സ) നിങ്ങൾക്ക് നൽകിയതെന്തോ അത് നിങ്ങൾ സ്വീകരിക്കുക. ഏതൊന്നിൽ നിന്ന് അവിടന്ന് നിങ്ങളെ വിലക്കിയോ അത് നിങ്ങൾ വെടിയുകയും ചെയ്യുക." (ഖുർആൻ 59: 7)', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=3);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', '"തീർച്ചയായും അല്ലാഹുവിന്റെ ദൂതനിൽ നിങ്ങൾക്ക് ഉത്തമ മാതൃകയുണ്ട്." (ഖുർആൻ 33: 21)', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=4);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'നബി(സ) പറഞ്ഞു: "ഞാൻ രണ്ടു കാര്യങ്ങൾ നിങ്ങൾക്കായി ബാക്കിവെച്ചാണ് പോകുന്നത്. അവ രണ്ടും മുറുകെ പിടിച്ചാൽ നിങ്ങൾ ഒരിക്കലും പിഴച്ചുപോകില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥവും പ്രവാചക ചര്യയുമത്രെ അത്." (മുവത്വ)', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=5);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', '(നബിയേ) നിങ്ങൾ പറയുക: "നിങ്ങൾ അല്ലാഹുവിനെ സ്നേഹിക്കുന്നുവെങ്കിൽ എന്നെ പിന്തുടരുക. അല്ലാഹു നിങ്ങളെയും സ്നേഹിക്കും." (ഖുർആൻ)', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=6);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', '''ഹദീസ് വിജ്ഞാനകോശം'' മതവിധികൾ യഥാവിധി മനസ്സിലാക്കാൻ സഹായിക്കുന്നു. ഇസ്ലാമിനെക്കുറിച്ച് അതിന്റെ ഉറവിടങ്ങളിൽ നിന്നുതന്നെ കൂടുതൽ അടുത്തറിയാൻ ഇതുപകരിക്കും. മതകർമ്മങ്ങൾ ചെയ്യുമ്പോൾ അതിന്റെ അടിസ്ഥാനം എന്താണെന്ന് നാം അറിഞ്ഞിരിക്കണം. നിലവിലുള്ള മിക്ക ഹദീസ് ഗ്രന്ഥങ്ങളും പല രൂപത്തിലാണ് ക്രോഡീകരിക്കപ്പെട്ടിട്ടുള്ളത്. അതുപോലെ ഹദീസുകളിൽ ഉപയോഗിക്കുന്ന പല പദങ്ങളും ഇപ്പോൾ പ്രയോഗത്തിൽ ഇല്ലാത്തതുകൊണ്ട് പല ഹദീസുകളുടെയും അർത്ഥം മനസ്സിലാക്കാൻ പ്രയാസമാണ്.', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=7);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'ബുഖാരി, മുസ്ലിം, അബൂദാവൂദ്, തുർമുദി, നസാഈ, ഇബ്നു മാജ എന്നീ ഗ്രന്ഥങ്ങളിലെ ഹദീസുകൾ ആവർത്തനം ഒഴിവാക്കി വിഷയ ക്രമത്തിൽ ക്രോഡീകരിച്ച് മലയാള പരിഭാഷയോടെയാണ് പ്രസിദ്ധീകരിക്കുന്നത്. സ്വിഹാഹുസ്സിത്തയിലെ ഒരു വിഷയത്തിലെ ഹദീസുകൾ മുഴുവൻ ഒന്നിച്ചുകാണാൻ എളുപ്പമായിരിക്കുന്നു. നബിചര്യ മനസ്സിലാക്കാനും ജീവിതത്തിൽ പകർത്താനും ആഗ്രഹിക്കുന്നവർക്ക് ഇത് സഹായകമാകട്ടെ എന്ന് പ്രാർത്ഥിക്കുന്നു.', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=8);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ആദ്യത്തെ രണ്ടുവാല്യവും വായിച്ച പലരും പല നിർദ്ദേശങ്ങളും നൽകിയിട്ടുണ്ട്. അവർക്കെല്ലാം നന്ദി പറയുന്നു. ഈ ഗ്രന്ഥങ്ങൾ കൂടുതൽ നന്നാക്കേണ്ടതുണ്ടെന്നറിയുന്നതിനാൽ ആവശ്യമായ നിർദ്ദേശങ്ങൾ വായനക്കാരിൽ നിന്ന് ആവശ്യപ്പെടുന്നു. കൂടുതൽ ആളുകളിലേക്ക് ഈ ഗ്രന്ഥങ്ങൾ എത്തിക്കാൻ എല്ലാവരുടെയും സഹായം അഭ്യർത്ഥിക്കുന്നു.', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=9);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'കേരളത്തിലെ എല്ലാ പള്ളികളിലും വീടുകളിലും ഇതിന്റെ കോപ്പി ഉണ്ടായിരിക്കണമെന്ന് ഞങ്ങൾ ആഗ്രഹിക്കുന്നു. ജാരിയായ സ്വദഖ (മരണാനന്തരവും ലഭിക്കുന്ന പുണ്യം) യായി ഈ ഗ്രന്ഥത്തിന്റെ കഴിയുന്നത്ര കോപ്പികൾ വാങ്ങി പള്ളികളിൽ വഖ്ഫ് ആക്കി വെക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു. നിങ്ങളുടെ സ്നേഹിതന്മാർക്ക് നൽകാവുന്ന ഒരു നല്ല സമ്മാനമായും ഹദീസ് വിജ്ഞാന കോശത്തെ ഉപയോഗപ്പെടുത്താവുന്നതാണ്.', null, '39' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=10);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച എല്ലാവർക്കും അല്ലാഹു മതിയായ പ്രതിഫലം നൽകുമാറാകട്ടെ. ആദ്യകാലത്ത് ഈ സംരംഭത്തിന് എല്ലാവിധ പ്രോൽസാഹനവും നൽകിയ വൈലത്തൂർ അബ്ദുർറഹ്മാൻ സാഹിബിനെ (അൽഅമാൻ ബുക്ക്സ്റ്റാൾ) ഇവിടെ സ്മരിക്കുന്നു.', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=11);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'മുൻവാല്യങ്ങൾക്കു പുറമെ ഹദീസ് വിജ്ഞാനകോശം മൂന്നാം വാല്യത്തിന്റെ ട്രാൻസ്ലേഷൻ, ടൈപിങ്, സെറ്റിങ്, എഡിറ്റിങ് തുടങ്ങിയവക്ക് ആദ്യാവസാനം സഹകരിച്ച പി.വി. ഉസ്മാൻ മഹ്ബൂബി വേങ്ങൂർ, എം.പി. മുഹമ്മദ് മൻസൂർ മഹ്ബൂബി ചാപ്പനങ്ങാടി, കെ.പി. ഖുബൈബ് മഹ്ബൂബി മാരിയാട്, എന്നിവർക്കും ഗ്രന്ഥം എഡിറ്റുചെയ്തു തന്ന അബ്ദുർറഹ്മാൻ മൗലവി പാണ്ടിക്കാടിനും പ്രത്യേകം കൃതജ്ഞത രേഖപ്പെടുത്തുന്നതോടൊപ്പം അവർക്ക് അല്ലാഹു ഉത്തമ പ്രതിഫലം നൽകട്ടെ എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു.', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=12);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'പ്രൊഫ: വി. മുഹമ്മദ് സാഹിബ്, എ. അബ്ദുസ്സലാം സാഹിബ്, ഡോ: അഹ്മദ് ഇസ്മാഈൽ ലബ്ബ, പ്രൊഫ: കെ. ഹബീബ പാഷ, ഡോ: കെ മുഹമ്മദ് ബഷീർ, മുഹമ്മദ് മുജീബ് കാളിയാർ, മുഹമ്മദ് ശരീഫ് വി.പി, ഇ.എം ശരീഫ് മുതുതല, എം.കെ ഹസ്സൻ കോട്ടുമല, വി.എ.എം ഇസ്ഹാഖ് നദ്വി, അബൂബക്കർ പി.കെ, ഉമർ കെ.പി, ഇബ്രാഹീം നദ്വി, എൻ.കെ, ഹുസൈൻ ഷംസുദ്ദീൻ വെളിയംകോട്, അമാനുല്ല എ.കെ, മുഹമ്മദ് അഷ്റഫ് മൗലവി, പ്രൊഫ: മുഹമ്മദ് കുട്ടശ്ശേരി, ഫാറൂഖ് അബ്ദുല്ല നാദാപുരം, ഇ. അബ്ദുൽ ലത്തീഫ്, എം.പി മുഹമ്മദ് ഫൈസൽ അഹ്സനി, അബ്ദുൽ ഖാദർ അഹ്സനി, ഹാരിസ് എം. ഹുദവി, മുഹമ്മദ് അലി ഹുദവി, അൻവർ എ.പി, ശുക്കൂർ.ടി മേലണ്ണം, കബീർ അഞ്ചച്ചവിടി, ഇസ്മാഈൽ എടക്കുളം, റഫീഖ് കെ മമ്പറം, അബ്ദുൽ മജീദ് എൻ.കെ, ഉമൈർ സി.കെ, എം.എ. ആരിഫ, ശുക്കൂർ വള്ളിക്കുന്ന്, സഈദ് കൊട്ടപ്പുറം, ശഫീഖ് സി.പി, റാഷിദ് സി.കെ, മൈമൂന സി.കെ, ആരിഫ പി.പി, സൽമ, വി.എം. കൂട്ടി മൗലവി, അബൂബക്കർ പോരൂർ, യൂനുസ്.കെ പേങ്ങാട്, ശഫീഖ് മഹ്ബൂബി എടയാറ്റൂർ, അശ്റഫ് മഹ്ബൂബി വെളിമുക്ക്, സുബൈർ മഹ്ബൂബി വേങ്ങര, ഹിദായത്തുല്ല മഹ്ബൂബി മുതുപറമ്പ്, റാഫി മഹ്ബൂബി ഇരിങ്ങാട്ടിരി, സ്വാലിഹ് മഹ്ബൂബി കുമരനല്ലൂർ, അബ്ദുറഹീം മഹ്ബൂബി ചങ്കുവെട്ടി, അബ്ദുൽഅസീസ് മഹ്ബൂബി പുലിക്കോട് എന്നിവർ ഈ സംരഭത്തിൾ സഹകരിച്ചവരാണ്. ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച മറ്റു വല്ലവരുടെയും പേരുകൾ വിട്ടുപോയിട്ടുണ്ടെങ്കിൽ ക്ഷമിക്കണമെന്നഭ്യർത്ഥിക്കുന്നു.', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=13);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'അൽഹംദു ലില്ലാഹ്!', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=14);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', '"അസ്സിഹാഹുസ്സിത്ത" എന്ന ഹദീസ് വിജ്ഞാനകോശത്തിന്റെ മൂന്നാം വാല്യം തയ്യാറാക്കാനും പ്രസിദ്ധീകരിക്കാനും സഹായിച്ച അല്ലാഹുവിന് സ്തുതി.', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=15);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'ഒന്നാം വാല്യത്തിന്റെ ആമുഖമായി പറഞ്ഞ കാര്യങ്ങൾ മൂന്നാം വാല്യത്തിൽ നിന്നൊഴിവാക്കുകയാണ്. ആദ്യമായി വായിച്ചുതുടങ്ങുന്നവർ ഒന്നാം വാല്യത്തിലെ ആദ്യ ഭാഗങ്ങൾ കൂടി വായിക്കണമെന്നഭ്യർത്ഥിക്കുന്നു.', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=16);
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'ഡോ: മുസ്തഫാ കമാൽ പാഷ', null, '40' from articles where volume_id=3 and section_no=1 and not exists (select 1 from article_blocks ab where ab.article_id=articles.id and ab.seq=17);
